now = datetime.datetime.now(datetime.timezone.utc).isoformat()

def put(n, x):
    p = H / n
    if p.exists():
        raise FileExistsError(p)
    p.write_text(json.dumps(x, indent=2, ensure_ascii=False) + '\n')
    return hashlib.sha256(p.read_bytes()).hexdigest()
